import re
import pandas as pd
r = pd.read_csv("reviews_text.csv")

def tokenize(text):
    return re.findall(r"[а-яё]+", text.lower())


def stem(word,n=5):
    return word[:n] if len(word)>n else word
w={w for t in r.text for w in tokenize(t)}
n_raw=len(w);n_stem=len({stem(x) for x in w})
merged=sorted(x for x in w if stem(x)==stem("курьер"))
